// The benchmark results page (#638). One data file, `benchmark_results.json` (contract v2 of the spec), drives it, and the file is checked
// IN CI by the vendored `scripts/benchmarks/validate_page_data.py` (reviews from both R1 and R2, recomputed hashes and intervals, labels
// that agree with p, every result sentence generated by template, banned-word lint on every string): the build fails on a non-zero exit,
// so no unreviewed number, banned word or unsigned result sentence reaches the page. This module is the RUNTIME side of the same rule:
// a block shows a figure only if it says `reviewed`, carries both reviews and structurally complete numbers; anything else is
// "Result pending" with no figure. The label comes before the number, and a number never appears without its "what it is not" line.
// No number lives in this file or in the page: every result sentence is read from the data.

export type BlockId = "bbl" | "citation" | "legalbench" | "sealed_court";
export type ReviewStatus = "reviewed" | "pending";
export type Outcome = "bar_met" | "bar_not_met" | "inconclusive" | "descriptive" | "n/a";

export const BLOCK_IDS: readonly BlockId[] = ["bbl", "citation", "legalbench", "sealed_court"];

/** Kind chips the validator allows (spec 2.2), and the ones each block may carry. */
export const KIND_CHIPS_BY_BLOCK: Readonly<Record<BlockId, readonly string[]>> = {
  bbl: ["Model legal knowledge (MCQ), not the harness"],
  citation: ["Citation checker, our own pre-registered study", "Own study, design not yet registered"],
  legalbench: ["Harness vs the same model alone; United States law"],
  sealed_court: ["Sealed Indian court test, reviewed result"],
};
export const DATA_CHIPS: readonly string[] = ["Real court-derived", "Public benchmark", "Model-generated questions", "Constructed"];

/** Outcome chips (reviewed blocks only). */
export const OUTCOME_LABEL: Readonly<Record<Exclude<Outcome, "n/a">, string>> = {
  bar_met: "Registered bar met",
  bar_not_met: "Registered bar not met",
  inconclusive: "Inconclusive",
  descriptive: "Descriptive",
};

export const PENDING_TEXT = "Result pending";
export const REVIEWED_TEXT = "Reviewed";

/** Block titles (spec 2.1, items 2 to 5). */
export const BLOCK_TITLE: Readonly<Record<BlockId, string>> = {
  bbl: "Our models on an Indian legal-knowledge test",
  citation: "Does our citation checker catch wrong citations?",
  legalbench: "Rule application on a public benchmark",
  sealed_court: "What the sealed Indian court tests found",
};

/** The fixed label shown on a block (spec 1.1 to 1.3); the sealed-court block carries the signed sentences from the data's `copy`. */
export const FIXED_LABEL: Readonly<Partial<Record<BlockId, string>>> = {
  bbl: "Model legal knowledge (multiple choice). Not the proof harness. Our models were not trained for this test.",
  citation:
    "Model-generated questions; Supreme Court judgments index only; a citation is checked for existence and metadata, not for whether the case supports a stated point. Questions were written by Anthropic Haiku and answered by Anthropic Sonnet.",
  legalbench:
    "United States law (public benchmark). A test of whether an element-by-element harness changes accuracy on a public rule-application task. Not the Indian-law claim. Not a placement on any public ranking.",
};

export const PAGE_TITLE = "Benchmarks";
export const PAGE_SUBTITLE = "What we test, how, and what the results do and do not show.";
export const NO_FIGURE_TEXT = "No figure is shown until a second reviewer has checked it.";

/** Block E, "How we test" (spec 2.1, item 6). */
export const HOW_WE_TEST: readonly string[] = [
  "Items are real court-derived or labelled constructed.",
  "Sealed sets are never used for tuning.",
  "Every number is checked by a second reviewer.",
  'Where two arms cannot be told apart the result is called "no separation", never a direction.',
  "Numbers are dated.",
];

/** Link text for a placement on the benchmark's own Space (the copy lint bans the stem of the usual word for it). */
export const RANK_LINK_TEXT = "Page of the Space";

export const FOOTER_TEXT = "Research results, not legal advice.";

export interface ResultRow {
  arm: string;
  group: string;
  protocol?: string;
  n: number;
  correct: number;
  accuracy: number;
  ci95: [number, number];
  invalid: number;
}
export interface ResultTable {
  title: string;
  columns: string[];
  rows: ResultRow[];
  /** Chance level (0 to 1) for the dashed line (an addition the spec's 2.3 asks for; absent means no line). */
  chance?: number;
}
export interface PairedResult {
  pair: string;
  only_first_correct: number;
  only_second_correct: number;
  p: number;
  holm_adjusted_p?: number | null;
  family: string;
  label: "no separation" | "separated";
  label_note?: string;
}
export interface BoundResult {
  name: string;
  kind: "one_sided_upper" | "one_sided_lower" | "two_sided";
  value: number;
  n: number;
  denominator: string;
}
export interface CategoryCount {
  label: string;
  count: number;
}
export interface Sentence {
  template_id: "accuracy" | "paired_no_separation" | "paired_separated" | "bound";
  text: string;
}
export interface Review {
  reviewer: "R1" | "R2";
  ref: string;
  head_sha: string;
  date: string;
}
export interface CopyItem {
  id: string;
  text: string;
  signed_source: { file: string; sha256: string } | null;
}
export interface Leaderboard {
  name: string;
  url: string;
  rank: number;
  as_of: string;
  submitted_by: string;
}

export interface ReviewedBlock {
  id: BlockId;
  review_status: "reviewed";
  outcome: Exclude<Outcome, "n/a">;
  reviews: Review[];
  kind_chip: string;
  data_chip: string;
  what_it_is: string;
  what_it_is_not: string;
  limits: string;
  copy: CopyItem[];
  sentences: Sentence[];
  run: { model_ids: string[]; revisions: string[]; dataset_revision: string; scorer_sha256: string; date: string };
  tables: ResultTable[];
  paired: PairedResult[];
  bounds: BoundResult[];
  categories: CategoryCount[];
  leaderboard: Leaderboard | null;
}

/** What the page renders for one block. `figures` is non-null ONLY for a reviewed block that passed the runtime checks. */
export interface BlockView {
  id: BlockId;
  title: string;
  /** "reviewed" only when figures are shown. */
  status: ReviewStatus;
  statusLabel: string;
  outcomeLabel: string | null;
  kindChip: string;
  dataChip: string | null;
  /** Why a block that claimed to be reviewed was refused (never shown on the page; for tests and the console). */
  refusal: string | null;
  fixedLabel: string | null;
  figures: ReviewedBlock | null;
}

export interface ParsedResults {
  generatedAt: string | null;
  pageVersion: string | null;
  blocks: BlockView[];
  problems: string[];
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}(?:T[0-9:.Z+-]+)?$/;
const HEX64 = /^[0-9a-f]{64}$/;
const SHA = /^[0-9a-f]{7,40}$/;
const REVIEW_URL = /^https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/pull\/\d+#pullrequestreview-\d+$/;

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
const isStr = (v: unknown): v is string => typeof v === "string" && v.trim() !== "";
const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const isInt = (v: unknown): v is number => isNum(v) && Number.isInteger(v) && v >= 0;
const isStrArray = (v: unknown): v is string[] => Array.isArray(v) && v.length > 0 && v.every(isStr);

function checkRow(r: unknown, where: string, errs: string[]): void {
  if (!isObj(r)) return void errs.push(`${where}: not an object`);
  const ci = r.ci95;
  if (!isStr(r.arm) || !isStr(r.group)) errs.push(`${where}: no arm or group`);
  if (!isInt(r.n) || r.n < 1) errs.push(`${where}: a number without its n`);
  if (!isInt(r.correct)) errs.push(`${where}: no correct count`);
  if (!isNum(r.accuracy) || r.accuracy < 0 || r.accuracy > 1) errs.push(`${where}: accuracy is not between 0 and 1`);
  if (!Array.isArray(ci) || ci.length !== 2 || !ci.every(isNum)) errs.push(`${where}: a number without its 95% interval`);
  else if (!(ci[0] >= 0 && ci[1] <= 1 && ci[0] <= ci[1])) errs.push(`${where}: the interval is not ordered inside 0 and 1`);
  else if (isNum(r.accuracy) && (r.accuracy < ci[0] - 1e-9 || r.accuracy > ci[1] + 1e-9)) errs.push(`${where}: accuracy lies outside its interval`);
  if (!isInt(r.invalid)) errs.push(`${where}: no invalid count`);
  if (isInt(r.n) && isInt(r.correct) && r.correct > r.n) errs.push(`${where}: more correct than n`);
  if (isInt(r.n) && isInt(r.correct) && isNum(r.accuracy) && r.n > 0 && Math.abs(r.correct / r.n - r.accuracy) > 0.005) errs.push(`${where}: accuracy does not equal correct / n`);
}

/** Why a block that says `reviewed` may not be shown; null when every runtime check passes. */
function refuseReviewed(id: BlockId, b: Record<string, unknown>): string | null {
  const errs: string[] = [];
  const reviews = Array.isArray(b.reviews) ? b.reviews : [];
  const who = new Set(reviews.filter(isObj).map((r) => r.reviewer));
  if (!(who.has("R1") && who.has("R2"))) errs.push("needs reviews from both R1 and R2");
  for (const r of reviews) {
    if (!isObj(r) || !isStr(r.ref) || !REVIEW_URL.test(r.ref) || !isStr(r.head_sha) || !SHA.test(r.head_sha) || !isStr(r.date) || !ISO_DATE.test(r.date)) errs.push("a review without its GitHub review link, head sha and date");
  }
  if (!isStr(b.numbers_file) || !isStr(b.numbers_sha256) || !HEX64.test(String(b.numbers_sha256))) errs.push("no numbers_file and numbers_sha256");
  const oc = b.outcome;
  if (!(oc === "bar_met" || oc === "bar_not_met" || oc === "inconclusive" || oc === "descriptive")) errs.push("a reviewed block needs an outcome");
  if (!isStr(b.kind_chip) || !KIND_CHIPS_BY_BLOCK[id].includes(b.kind_chip)) errs.push("kind chip is not one this block may carry");
  if (!isStr(b.data_chip) || !DATA_CHIPS.includes(b.data_chip)) errs.push("data chip is not in the fixed vocabulary");
  for (const f of ["what_it_is", "what_it_is_not", "limits"]) if (!isStr(b[f])) errs.push(`no ${f} (a number never appears without its what-it-is-not line)`);
  const run = b.run;
  if (!isObj(run) || !isStrArray(run.model_ids) || !isStrArray(run.revisions) || !isStr(run.dataset_revision) || !isStr(run.scorer_sha256) || !HEX64.test(String(run.scorer_sha256)) || !isStr(run.date) || !ISO_DATE.test(String(run.date))) {
    errs.push("run record incomplete (model ids, revisions, dataset revision, scorer sha256, date)");
  }
  const tables = Array.isArray(b.tables) ? b.tables : [];
  const paired = Array.isArray(b.paired) ? b.paired : [];
  const bounds = Array.isArray(b.bounds) ? b.bounds : [];
  const categories = Array.isArray(b.categories) ? b.categories : [];
  if (tables.length + paired.length + bounds.length === 0) errs.push("no tables, paired tests or bounds");
  tables.forEach((t, ti) => {
    if (!isObj(t) || !isStr(t.title) || !Array.isArray(t.columns) || !Array.isArray(t.rows) || t.rows.length === 0) return void errs.push(`table ${ti + 1}: needs a title, columns and rows`);
    if (t.chance !== undefined && !(isNum(t.chance) && t.chance > 0 && t.chance < 1)) errs.push(`table ${ti + 1}: chance is not between 0 and 1`);
    t.rows.forEach((r, ri) => checkRow(r, `table ${ti + 1} row ${ri + 1}`, errs));
  });
  paired.forEach((p, pi) => {
    if (!isObj(p) || !isStr(p.pair) || !isInt(p.only_first_correct) || !isInt(p.only_second_correct) || !isNum(p.p) || p.p < 0 || p.p > 1 || !isStr(p.family)) return void errs.push(`paired ${pi + 1}: needs a pair, both discordant counts, a p value and a family`);
    if (p.label !== "no separation" && p.label !== "separated") return void errs.push(`paired ${pi + 1}: label is not "no separation" or "separated"`);
    const adj = isNum(p.holm_adjusted_p) && !String(p.family).startsWith("none") ? p.holm_adjusted_p : p.p;
    // A direction is stated only when the (Holm-adjusted, when a family is named) p is below 0.05.
    if ((adj >= 0.05) !== (p.label === "no separation")) errs.push(`paired ${pi + 1}: the label contradicts p (p >= 0.05 is "no separation")`);
  });
  bounds.forEach((bd, bi) => {
    if (!isObj(bd) || !isStr(bd.name) || !isNum(bd.value) || !isInt(bd.n) || (bd.n as number) < 1 || !isStr(bd.denominator) || !["one_sided_upper", "one_sided_lower", "two_sided"].includes(String(bd.kind))) errs.push(`bound ${bi + 1}: needs a name, kind, value, n and denominator`);
  });
  categories.forEach((c, ci) => {
    if (!isObj(c) || !isStr(c.label) || !isInt(c.count)) errs.push(`category ${ci + 1}: needs a label and a count`);
  });
  // Every figure on the page is read as a generated sentence: numbers without their sentence are not shown.
  const sentences = Array.isArray(b.sentences) ? b.sentences : [];
  const needed = tables.reduce<number>((a, t) => a + (isObj(t) && Array.isArray(t.rows) ? t.rows.length : 0), 0) + paired.length + bounds.length;
  if (sentences.length < needed || !sentences.every((s) => isObj(s) && isStr(s.text) && isStr(s.template_id))) errs.push("every figure needs its generated result sentence");
  const lb = b.leaderboard;
  if (lb !== null && lb !== undefined) {
    if (!isObj(lb) || !isStr(lb.name) || !isStr(lb.url) || !/^https:\/\/huggingface\.co\/spaces\//.test(String(lb.url)) || !isInt(lb.rank) || !isStr(lb.as_of) || !ISO_DATE.test(String(lb.as_of)) || !isStr(lb.submitted_by)) {
      errs.push("leaderboard needs the Space's own https url, rank, as_of date and submitted_by (or null)");
    }
  }
  return errs.length ? errs.join("; ") : null;
}

function pendingView(id: BlockId, b: Record<string, unknown> | undefined, refusal: string | null): BlockView {
  const kind = b && isStr(b.kind_chip) && KIND_CHIPS_BY_BLOCK[id].includes(b.kind_chip) ? b.kind_chip : KIND_CHIPS_BY_BLOCK[id][0];
  const data = b && isStr(b.data_chip) && DATA_CHIPS.includes(b.data_chip) ? b.data_chip : null;
  return { id, title: BLOCK_TITLE[id], status: "pending", statusLabel: PENDING_TEXT, outcomeLabel: null, kindChip: kind, dataChip: data, refusal, fixedLabel: FIXED_LABEL[id] ?? null, figures: null };
}

/**
 * Read the data file. The result ALWAYS has the four blocks, in the page order; a block missing from the file, pending, or failing a
 * runtime check is "Result pending" with no figure. Never throws; never lets a figure through on a doubtful block.
 */
export function parseBenchmarkResults(raw: unknown): ParsedResults {
  const problems: string[] = [];
  const out: ParsedResults = { generatedAt: null, pageVersion: null, blocks: [], problems };
  const file = isObj(raw) ? raw : null;
  if (!file) problems.push("the results file is not an object");
  else {
    if (isStr(file.generated_at) && ISO_DATE.test(file.generated_at)) out.generatedAt = file.generated_at;
    else problems.push("generated_at is missing or not a date");
    if (isStr(file.page_version)) out.pageVersion = file.page_version;
    else problems.push("page_version is missing");
  }
  const list = file && Array.isArray(file.blocks) ? file.blocks : [];
  if (file && !Array.isArray(file.blocks)) problems.push("blocks is not a list");
  const byId = new Map<BlockId, Record<string, unknown>>();
  for (const b of list) {
    if (!isObj(b) || !BLOCK_IDS.includes(b.id as BlockId)) {
      problems.push("a block with an unknown id was ignored");
      continue;
    }
    if (byId.has(b.id as BlockId)) {
      problems.push(`block ${String(b.id)} appears twice; only the first is read`);
      continue;
    }
    byId.set(b.id as BlockId, b);
  }
  for (const id of BLOCK_IDS) {
    const b = byId.get(id);
    if (!b) {
      out.blocks.push(pendingView(id, undefined, null));
      continue;
    }
    if (b.review_status !== "reviewed") {
      if (b.review_status !== "pending") problems.push(`block ${id}: unknown review_status, treated as pending`);
      const carries = ["tables", "paired", "bounds", "categories"].some((k) => Array.isArray(b[k]) && (b[k] as unknown[]).length > 0);
      if (carries) problems.push(`block ${id}: pending but carries figures; they are not shown`);
      out.blocks.push(pendingView(id, b, carries ? "figures on a block that is not reviewed" : null));
      continue;
    }
    const refusal = refuseReviewed(id, b);
    if (refusal) {
      problems.push(`block ${id}: refused (${refusal})`);
      out.blocks.push(pendingView(id, b, refusal));
      continue;
    }
    const f = b as unknown as ReviewedBlock;
    out.blocks.push({
      id,
      title: BLOCK_TITLE[id],
      status: "reviewed",
      statusLabel: REVIEWED_TEXT,
      outcomeLabel: OUTCOME_LABEL[f.outcome],
      kindChip: f.kind_chip,
      dataChip: f.data_chip,
      refusal: null,
      fixedLabel: FIXED_LABEL[id] ?? null,
      figures: f,
    });
  }
  return out;
}

/** The title as shown: an inconclusive result says so in its title (spec 2.1, block B). */
export function titleFor(v: BlockView): string {
  return v.figures && v.figures.outcome === "inconclusive" ? `${v.title} (Inconclusive)` : v.title;
}

/** The names of the two arms of a "A vs B" pair. */
export function pairNames(pair: string): [string, string] {
  const [a, b] = pair.split(" vs ");
  return [a?.trim() || "first arm", b?.trim() || "second arm"];
}

/** Text alternative for a table's chart: every row with its n and interval, in the order given (never sorted by value). */
export function chartAlt(t: ResultTable): string {
  const pct = (x: number) => `${(x * 100).toFixed(1)}%`;
  return `${t.title}. ${t.rows.map((r) => `${r.arm}, ${r.group}: ${pct(r.accuracy)}, 95% interval ${pct(r.ci95[0])} to ${pct(r.ci95[1])}, n ${r.n}`).join("; ")}.${t.chance !== undefined ? ` Chance level ${pct(t.chance)}.` : ""}`;
}

/** Every fixed string the page shows (for the copy lint in the tests and in CI); no data-file text. */
export function fixedPageStrings(): { id: string; text: string }[] {
  const items: { id: string; text: string }[] = [];
  const add = (id: string, text: string | undefined) => text && items.push({ id, text });
  add("subtitle", PAGE_SUBTITLE);
  add("footer", FOOTER_TEXT);
  add("rank-link", RANK_LINK_TEXT);
  add("no-figure", NO_FIGURE_TEXT);
  add("pending", PENDING_TEXT);
  add("reviewed", REVIEWED_TEXT);
  HOW_WE_TEST.forEach((t, i) => add(`how-${i}`, t));
  for (const id of BLOCK_IDS) {
    add(`title-${id}`, BLOCK_TITLE[id]);
    add(`label-${id}`, FIXED_LABEL[id]);
    KIND_CHIPS_BY_BLOCK[id].forEach((k, i) => add(`kind-${id}-${i}`, k));
  }
  DATA_CHIPS.forEach((d, i) => add(`data-${i}`, d));
  Object.entries(OUTCOME_LABEL).forEach(([k, v]) => add(`outcome-${k}`, v));
  return items;
}
